    /**
     * 内部775→クライアントのプレイ状態（サーバー→クライアント）。
     * Join Game／Respawn／Spawn Position／Keep Alive／Ping／Disconnect／
     * Start Configuration は774と同形式（ID も同じ）のため、774の処理を使い回す。
     * ただし774クライアントへの送出だけは775→774へ直すため、
     * Join Game／Respawn／Disconnect には774向けの分岐がある。
     * それ以外は775→774へ変換してから、774クライアントにはそのまま送り、
     * 767／766クライアントには既存の774→773／766の処理に通す。
     * 763／764／765クライアントは join レベルのみ（774と同じ）。
     */
    private Outcome handleServerPlayFrom775(MinecraftPacket packet) {
        // Start Configuration（775：0x76）。763には設定フェーズもこのパケットも無い。
        if (packet.id() == 0x76) {
            if (is763() || is757()) {
                serverState = ServerState.CONFIGURATION;
                reconfiguring = true;
                LOG.info(() -> "プレイ中の Start Configuration を受けました（" + playerName
                        + "）。サーバー側の設定フェーズを肩代わりします。");
                return Outcome.drop();
            }
            int outId = PacketTranslator.translateId(
                    PacketName.PLAY_START_CONFIGURATION, 775, clientProtocol)
                    .orElse(is764() ? 0x65 : 0x67);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        // Join Game（775：0x31）。
        if (packet.id() == 0x31) {
            return handleServerJoinGame775(packet);
        }
        // Spawn Position（775：0x61）。
        if (packet.id() == 0x61) {
            advanceFlowSafely(() -> joinFlow.spawned());
            int outId = PacketTranslator.translateId(
                    PacketName.PLAY_SPAWN_POSITION, 775, clientProtocol)
                    .orElse(is764() ? 0x52 : 0x54);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        // Keep Alive（775：0x2C）／Ping（775：0x3D）は接続維持のため中継する。
        if (packet.id() == 0x2C) {
            int outId = PacketTranslator.toClientId(PacketName.PLAY_KEEP_ALIVE,
                    serverProtocol, clientProtocol)
                    .orElse(is763() ? 0x23 : 0x24);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        if (packet.id() == 0x3D) {
            int outId = PacketTranslator.toClientId(PacketName.PLAY_PING,
                    serverProtocol, clientProtocol)
                    .orElse(is763() ? 0x32 : 0x33);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        // Disconnect（775：0x20、NBT）。
        if (packet.id() == 0x20) {
            closed = true;
            if (is763() || is764() || is757()) {
                byte[] payload = PlayTranslator.translateDisconnect765To763(packet.payload());
                int outId = (is763() || is757()) ? 0x1A : 0x1B;
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(outId, payload)), false, true);
            }
            if (is773() || is774() || is775()) {
                // 773／774／775クライアント：Disconnect は 0x20（NBT）のまま。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x20, packet.payload())), false, true);
            }
            if (is770() || is771() || is772()) {
                // 770／771／772クライアント：Disconnect は 0x1C（NBT）のまま。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x1C, packet.payload())), false, true);
            }
            if (is766() || is767() || is768() || is769()) {
                // 766／767／768／769クライアント：Disconnect は 0x1D（NBT）のまま。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x1D, packet.payload())), false, true);
            }
            return new Outcome(List.of(),
                    List.of(new MinecraftPacket(0x1B, packet.payload())), false, true);
        }
        // Respawn（775：0x52。774（0x50）と同形式のためそのまま送る）。
        if (packet.id() == 0x52) {
            if (is757()) {
                // 757クライアント：775の Respawn は dimensionType がキー形式で757と違うため落とす
                // （変換は PlayTranslator 担当。translateRespawn775To757 が要る）。
                logUntranslatedOnce(PacketName.PLAY_RESPAWN);
                return Outcome.drop();
            }
            if (is774()) {
                // 774クライアント：Respawn は 0x50（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x50, packet.payload()));
            }
            if (is773()) {
                // 773クライアント：Respawn は 0x50（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x50, packet.payload()));
            }
            if (is770() || is771() || is772()) {
                // 770／771／772クライアント：Respawn は 0x4B（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x4B, packet.payload()));
            }
            if (is768() || is769()) {
                // 768／769クライアント：Respawn は 0x4C（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x4C, packet.payload()));
            }
            byte[] payload767 = PlayTranslator.translateRespawn768To767(
                    packet.payload(), registries);
            if (is766() || is767()) {
                return Outcome.toClient(new MinecraftPacket(0x47, payload767));
            }
            byte[] payload;
            int outId;
            if (is763()) {
                payload = PlayTranslator.translateRespawn766To763(payload767, registries);
                outId = 0x41;
            } else if (is764()) {
                payload = PlayTranslator.translateRespawn766To764(payload767, registries);
                outId = 0x43;
            } else {
                payload = PlayTranslator.translateRespawn766To765(payload767, registries);
                outId = 0x45;
            }
            return Outcome.toClient(new MinecraftPacket(outId, payload));
        }
        // 774クライアント：775→774へ変換する。
        if (is774()) {
            return handleServerPlay775To774(packet);
        }
        // 767クライアント：775→774→773→772→771→770→769→768へ変換してから769→768へ。
        if (is767()) {
            MinecraftPacket as774 = to774ServerPacketFrom775(packet);
            if (as774 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as773 = to773ServerPacketFrom774(as774);
            if (as773 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as772 = to772ServerPacketFrom773(as773);
            if (as772 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as771 = to771ServerPacketFrom772(as772);
            if (as771 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as770 = to770ServerPacketFrom771(as771);
            if (as770 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as769 = to769ServerPacketFrom770(as770);
            if (as769 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as768 = to768ServerPacket(as769);
            if (as768 == null) {
                return Outcome.drop();
            }
            return handleServerPlay768To767(as768);
        }
        // 766クライアント：775→774→773→772→771→770→769→768へ変換してから768→766へ。
        if (is766()) {
            MinecraftPacket as774 = to774ServerPacketFrom775(packet);
            if (as774 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as773 = to773ServerPacketFrom774(as774);
            if (as773 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as772 = to772ServerPacketFrom773(as773);
            if (as772 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as771 = to771ServerPacketFrom772(as772);
            if (as771 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as770 = to770ServerPacketFrom771(as771);
            if (as770 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as769 = to769ServerPacketFrom770(as770);
            if (as769 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as768 = to768ServerPacket(as769);
            if (as768 == null) {
                return Outcome.drop();
            }
            return handleServerPlay768To766(as768);
        }
        // それ以外は落とす（763／764／765クライアントは join レベルのみ）。
        PacketName name = PacketIds.nameFor(packet.id(), State.PLAY,
                Direction.CLIENTBOUND, 775).orElse(null);
        if (name == null) {
            logUntranslatedOnce("PLAY_UNKNOWN_0x" + Integer.toHexString(packet.id()));
        } else {
            logUntranslatedOnce(name);
        }
        return Outcome.drop();
    }

    /**
     * Join Game（内部775：0x31）のクライアント向け変換。
     * 774と同形式のため、774クライアントにはそのまま送る。
     * それ以外は {@link #handleServerJoinGame774} と同じ方針で各クライアントへ送る。
     */
    private Outcome handleServerJoinGame775(MinecraftPacket packet) {
        if (is757()) {
            // 757クライアント：775の Join Game は dimensionType がキー形式で757と違うため落とす
            // （変換は PlayTranslator 担当。translateJoinGame775To757 が要る）。
            logUntranslatedOnce(PacketName.PLAY_JOIN_GAME);
            return Outcome.drop();
        }
        if (is774()) {
            advanceFlowSafely(() -> joinFlow.joinGameReceived());
            List<MinecraftPacket> toClient = new ArrayList<>();
            toClient.add(new MinecraftPacket(0x30, packet.payload()));
            while (!pendingPacks.isEmpty()) {
                PendingPack pack = pendingPacks.removeFirst();
                lastSentPack = pack;
                toClient.add(new MinecraftPacket(0x4F,
                        PlayTranslator.translateConfigAddResourcePack764To765(
                                pack, packOverrideForClient())));
            }
            return new Outcome(List.of(), toClient, false, false);
        }
        return handleServerJoinGame774(packet);
    }

    /**
     * 775サーバーのプレイ状態パケットを774形式にする。774に相当が無い／
     * 変換できないものは null を返す（ログ済み）。
     * 774クライアントへの送出と、767／766クライアントへの二段変換の
     * 第一段で共用する。
     */
    private MinecraftPacket to774ServerPacketFrom775(MinecraftPacket packet) {
        PacketName name = PacketIds.nameFor(packet.id(), State.PLAY,
                Direction.CLIENTBOUND, ProtocolVersion.V26_1).orElse(null);
        // experience_orb：771・772・773・774・775とも通常の Spawn Entity
        // （type experience_orb）のため、専用の分岐は要らない
        // （下の PLAY_SPAWN_ENTITY 経路で通す）。
        if (name == null) {
            logUntranslatedOnce("PLAY_UNKNOWN_0x" + Integer.toHexString(packet.id()));
            return null;
        }
        byte[] translated = switch (name) {
            case PLAY_ENTITY_METADATA ->
                    ChunkTranslator.translateEntityMetadata775To774(packet.payload());
            case PLAY_SET_SLOT ->
                    ChunkTranslator.translateSetSlot775To774(packet.payload());
            case PLAY_SET_CURSOR_ITEM ->
                    ChunkTranslator.translateSetCursorItem775To774(packet.payload());
            case PLAY_SET_PLAYER_INVENTORY ->
                    ChunkTranslator.translateSetPlayerInventory775To774(packet.payload());
            case PLAY_WINDOW_ITEMS ->
                    ChunkTranslator.translateWindowItems775To774(packet.payload());
            case PLAY_SET_COOLDOWN ->
                    ChunkTranslator.translateSetCooldown775To774(packet.payload());
            case PLAY_ENTITY_EQUIPMENT ->
                    ChunkTranslator.translateEntityEquipment775To774(packet.payload());
            case PLAY_TRADE_LIST ->
                    ChunkTranslator.translateTradeList775To774(packet.payload());
            case PLAY_OPEN_WINDOW ->
                    ChunkTranslator.translateOpenWindow775To774(packet.payload());
            case PLAY_BLOCK_ACTION ->
                    ChunkTranslator.translateBlockAction775To774(packet.payload());
            case PLAY_SPAWN_ENTITY ->
                    ChunkTranslator.translateSpawnEntity775To774(packet.payload());
            case PLAY_SOUND_EFFECT ->
                    ChunkTranslator.translateSoundEffect775To774(packet.payload());
            case PLAY_ENTITY_SOUND_EFFECT ->
                    ChunkTranslator.translateEntitySoundEffect775To774(packet.payload());
            case PLAY_STOP_SOUND ->
                    ChunkTranslator.translateStopSound775To774(packet.payload());
            case PLAY_WORLD_PARTICLES ->
                    ChunkTranslator.translateWorldParticles775To774(packet.payload());
            case PLAY_ENTITY_EFFECT ->
                    ChunkTranslator.translateEntityEffect775To774(packet.payload());
            case PLAY_REMOVE_ENTITY_EFFECT ->
                    ChunkTranslator.translateRemoveEntityEffect775To774(packet.payload());
            case PLAY_DAMAGE_EVENT ->
                    ChunkTranslator.translateDamageEvent775To774(packet.payload());
            case PLAY_ENTITY_UPDATE_ATTRIBUTES ->
                    ChunkTranslator.translateUpdateAttributes775To774(packet.payload());
            case PLAY_CHUNK_DATA ->
                    ChunkTranslator.translateChunkData775To774(packet.payload());
            case PLAY_BLOCK_CHANGE ->
                    ChunkTranslator.translateBlockChange775To774(packet.payload());
            case PLAY_MULTI_BLOCK_CHANGE ->
                    ChunkTranslator.translateMultiBlockChange775To774(packet.payload());
            case PLAY_BLOCK_ENTITY_DATA ->
                    ChunkTranslator.translateBlockEntityData775To774(packet.payload());
            case PLAY_PLAYER_INFO_UPDATE ->
                    PlayTranslator.translatePlayerInfo775To774(packet.payload());
            case PLAY_PLAYER_CHAT ->
                    PlayTranslator.translatePlayerChat775To774(packet.payload());
            case PLAY_SYSTEM_CHAT, PLAY_PROFILELESS_CHAT ->
                    packet.payload(); // 同形式
            case PLAY_SYNCHRONIZE_PLAYER_POSITION, PLAY_SET_SLOT_STATE ->
                    packet.payload(); // 同形式
            case PLAY_UPDATE_TIME ->
                    PlayTranslator.translateUpdateTime775To774(packet.payload());
            case PLAY_HELD_ITEM_SLOT ->
                    PlayTranslator.translateSetHeldItem775To774(packet.payload());
            case PLAY_EXPLOSION ->
                    ChunkTranslator.translateExplosion775To774(packet.payload());
            // ロケーターバー／ダイアログは774にもあるためそのまま通す（同形式）。
            case PLAY_TRACKED_WAYPOINT, PLAY_SHOW_DIALOG, PLAY_CLEAR_DIALOG ->
                    packet.payload();
            default -> null;
        };
        if (translated == null) {
            logUntranslatedOnce(name);
            return null;
        }
        OptionalInt id774 = PacketTranslator.translateId(name,
                ProtocolVersion.V26_1, ProtocolVersion.V1_21_11);
        if (id774.isEmpty()) {
            logUntranslatedOnce(name);
            return null;
        }
        return new MinecraftPacket(id774.getAsInt(), translated);
    }

    /**
     * 内部775→774クライアントのプレイ状態（サーバー→クライアント）。
     * 775→774へ変換してそのまま送る。
     */
    private Outcome handleServerPlay775To774(MinecraftPacket packet) {
        MinecraftPacket as774 = to774ServerPacketFrom775(packet);
        if (as774 == null) {
            return Outcome.drop();
        }
        return Outcome.toClient(as774);
    }

    /**
     * 内部759のプレイ状態（サーバー→クライアント）。
     * プレイ状態のパケットIDは760と違うものがある。ペイロードが
     * 違うものだけ760形式へ直してから、760サーバー扱いで処理する。
     * Player Info だけは1個の759パケットが複数個の761パケットになるため、
     * ここで展開してから1個ずつ処理する。759の Player Info は760と
     * 同じ旧式（action VarInt）のため、760→761の展開をそのまま使える。
     * 変換できないもの（ブロックエンティティ種別が範囲外など）は落とす。
     */
    private Outcome handleServerPlayFrom759(MinecraftPacket packet) {
        PacketName name759 = PacketIds.nameFor(packet.id(), State.PLAY,
                Direction.CLIENTBOUND, 759).orElse(null);
        if (name759 == PacketName.PLAY_PLAYER_INFO_UPDATE) {
            List<byte[]> expanded =
                    PlayTranslator.translatePlayerInfo760To761(packet.payload());
            List<MinecraftPacket> toClient = new ArrayList<>();
            List<MinecraftPacket> toServer = new ArrayList<>();
            boolean relay = false;
            boolean closeAfterSend = false;
            for (byte[] payload761 : expanded) {
                MinecraftPacket p761 = new MinecraftPacket(PacketIds.id(
                        PacketName.PLAY_PLAYER_INFO_UPDATE, State.PLAY,
                        Direction.CLIENTBOUND, 761).orElseThrow(), payload761);
                MinecraftPacket to762 = to762ServerPacket(p761);
                if (to762 == null) {
                    continue;
                }
                MinecraftPacket converted = to763ServerPacket(to762);
                if (converted == null) {
                    continue;
                }
                Outcome outcome = handleServerPlayFrom763(converted);
                toServer.addAll(outcome.toServer());
                toClient.addAll(outcome.toClient());
                relay |= outcome.relay();
                closeAfterSend |= outcome.closeAfterSend();
            }
            return new Outcome(toServer, toClient, relay, closeAfterSend);
        }
        MinecraftPacket to760 = to760ServerPacket759(packet);
        if (to760 == null) {
            return Outcome.drop();
        }
        MinecraftPacket to761 = to761ServerPacket(to760);
        if (to761 == null) {
            return Outcome.drop();
        }
        MinecraftPacket to762 = to762ServerPacket(to761);
        if (to762 == null) {
            return Outcome.drop();
        }
        MinecraftPacket converted = to763ServerPacket(to762);
        if (converted == null) {
            return Outcome.drop();
        }
        return handleServerPlayFrom763(converted);
    }

    /**
     * 内部757のプレイ状態（サーバー→クライアント）。
     * Join Game（0x26）／Spawn Position（0x4B）／Keep Alive（0x21）／
     * Ping（0x30）／Disconnect（0x1A、JSON 文字列）はここで処理する。
     * Respawn（0x3D）は757クライアントにはそのまま送り、それ以外は
     * dimensionType が値（NBT）で759と違うため落とす（素通し禁止。
     * 変換は PlayTranslator 担当。translateRespawn757To759 が要る）。
     * 759以上クライアントには {@link #to759ServerPacketFrom757} で757→759へ変換してから
     * {@link #handleServerPlayFrom759} に委譲する（二段変換。Join Game／Respawn も同じ）。
     * 757・759とも設定フェーズは無いため、Start Configuration は無い。
     * 注意：ここから直接クライアント形式のパケットを返してはいけない。
     * 呼び出し側 handleServerPlay が結果を763形式とみなして759〜762向けに
     * 変換し直すため、759形式の ID（Join Game 0x23、Keep Alive 0x1E など）は
     * 763の別パケットと誤読されて壊れる。
     */
    private Outcome handleServerPlayFrom757(MinecraftPacket packet) {
        // Join Game（757：0x26）。
        if (packet.id() == 0x26) {
            return handleServerJoinGame757(packet);
        }
        // Spawn Position（757：0x4B）。
        // 757クライアントにはそのまま送る。759以上は汎用経路に任せる
        // （直接759形式 0x4A で返すと、呼び出し側 handleServerPlay が
        // 0x4A を763の World Border Warning Delay と誤読して ID を壊す）。
        if (packet.id() == 0x4B) {
            advanceFlowSafely(() -> joinFlow.spawned());
            if (is757()) {
                return Outcome.toClient(new MinecraftPacket(0x4B, packet.payload()));
            }
        }
        // Keep Alive（757：0x21）／Ping（757：0x30）／Disconnect（757：0x1A）は
        // 汎用経路に任せる（to759ServerPacketFrom757 で素通し→
        // handleServerPlayFrom759 の連鎖→呼び出し側の変換）。
        // 直接クライアント形式で返すと、呼び出し側 handleServerPlay が
        // 759形式の ID を763形式と誤読する（Keep Alive 0x1E→Unload Chunk、
        // Ping 0x2D→Entity Look、Disconnect 0x17→Plugin Message）。
        // Respawn（757：0x3D）。
        if (packet.id() == 0x3D) {
            if (is757()) {
                // 757クライアント：そのまま送る。
                return Outcome.toClient(new MinecraftPacket(0x3D, packet.payload()));
            }
            // 759形式に変換する（759の Respawn は 0x3B。dimension は NBT の値から名前に直す）。
            // 759形式にしてから759の処理に任せる（759→760→761→762→763の既存の
            // 連鎖で763形式になり、呼び出し側 handleServerPlay の変換で
            // クライアントの形式に戻る）。直接759形式で返すと、呼び出し側が
            // 0x3B を763形式と誤読して ID を壊すため、直接返してはいけない。
            byte[] as759 = PlayTranslator.translateRespawn757To759(packet.payload());
            return handleServerPlayFrom759(new MinecraftPacket(0x3B, as759));
        }
        // 759以上クライアント：757→759へ変換してから759の処理に任せる
        // （759→760→761→762→763の既存の連鎖で763形式になり、呼び出し側
        // handleServerPlay の変換でクライアントの形式に戻る）。
        // handleServerPlay757To759 のように直接759形式で返すと、呼び出し側が
        // パケットを763形式と誤読して ID を壊すため、直接返してはいけない。
        MinecraftPacket as759 = to759ServerPacketFrom757(packet);
        if (as759 == null) {
            return Outcome.drop();
        }
        return handleServerPlayFrom759(as759);
    }

    /**
     * Join Game（内部757：0x26）のクライアント向け変換。
     * 757クライアントにはそのまま送る（Join Game 0x26、Resource Pack 0x3C）。
     * 759以上クライアントには757→759へ変換してから759の処理に任せる
     * （759→760→761→762→763の既存の連鎖で763形式になり、呼び出し側
     * handleServerPlay の変換でクライアントの形式に戻る）。
     * 757の Join Game は dimensionType が値（NBT）で759と違うため素通し禁止。
     */
    private Outcome handleServerJoinGame757(MinecraftPacket packet) {
        if (is757()) {
            advanceFlowSafely(() -> joinFlow.joinGameReceived());
            List<MinecraftPacket> toClient = new ArrayList<>();
            toClient.add(new MinecraftPacket(0x26, packet.payload()));
            while (!pendingPacks.isEmpty()) {
                PendingPack pack = pendingPacks.removeFirst();
                lastSentPack = pack;
                toClient.add(new MinecraftPacket(0x3C,
                        PlayTranslator.buildPlayResourcePack763(pack, packOverrideForClient())));
            }
            return new Outcome(List.of(), toClient, false, false);
        }
        // 759以上クライアント：757→759へ変換してから759の処理に任せる
        // （759→760→761→762→763の既存の連鎖で763形式になり、呼び出し側
        // handleServerPlay の変換でクライアントの形式に戻る。Join Game は
        // 762→763で translateJoinGame762To763 が portalCooldown を補い、
        // 呼び出し側で763→759へ戻る。直接759形式（0x23）で返すと、
        // 呼び出し側が 0x23 を763の Keep Alive と誤読して ID を壊すため、
        // 直接返してはいけない）。
        byte[] as759 = PlayTranslator.translateJoinGame757To759(packet.payload());
        return handleServerPlayFrom759(new MinecraftPacket(0x23, as759));
    }

    /**
     * 757サーバーのプレイ状態パケットを759形式にする。759に相当が無い／
     * 変換できないものは null を返す（ログ済み）。
     * 759クライアントへの送出と、760以上クライアントへの二段変換の
     * 第一段で共用する。
     * ペイロード変換が要るものは PlayTranslator／ChunkTranslator の
     * *757To759 変換器を呼ぶ。同形式のもの（Update Time、Held Item Slot、
     * Synchronize Player Position、Block Entity Data、Explosion、
     * Entity Update Attributes）は素通しする（minecraft-data 1.18／1.19で
     * フィールド一致を確認）。Spawn Entity Living／Painting／Chat は出力IDが
     * 変わる（spawn_entity 0x00／system_chat 0x5F）ため switch の前で処理する。
     * Acknowledge Player Digging は再構成できないため落とす。Sculk Vibration
     * Signal は759に相当が無いため落とす。
     */
    private MinecraftPacket to759ServerPacketFrom757(MinecraftPacket packet) {
        PacketName name = PacketIds.nameFor(packet.id(), State.PLAY,
                Direction.CLIENTBOUND, ProtocolVersion.V1_18).orElse(null);
        if (name == null) {
            logUntranslatedOnce("PLAY_UNKNOWN_0x" + Integer.toHexString(packet.id()));
            return null;
        }
        // 757の新規パケット：759の別パケットへ統合する（出力IDが変わるため switch の前に処理する）。
        if (name == PacketName.PLAY_SPAWN_ENTITY_LIVING) {
            // 759の spawn_entity は 0x00（packet-ids-757.json で確認）。
            return new MinecraftPacket(0x00,
                    PlayTranslator.translateSpawnEntityLiving757ToSpawnEntity759(packet.payload()));
        }
        if (name == PacketName.PLAY_SPAWN_ENTITY_PAINTING) {
            return new MinecraftPacket(0x00,
                    PlayTranslator.translateSpawnEntityPainting757ToSpawnEntity759(packet.payload()));
        }
        if (name == PacketName.PLAY_CHAT) {
            // 757の chat（0x0F）→759の system_chat 0x5F（packet-ids-757.json で確認）。
            return new MinecraftPacket(0x5F,
                    PlayTranslator.translateChat757ToSystemChat(packet.payload()));
        }
        byte[] translated = switch (name) {
            case PLAY_ENTITY_METADATA -> ChunkTranslator.translateEntityMetadata757To759(packet.payload());
            case PLAY_SET_SLOT -> ChunkTranslator.translateSetSlot757To759(packet.payload());
            case PLAY_WINDOW_ITEMS -> ChunkTranslator.translateWindowItems757To759(packet.payload());
            case PLAY_SET_COOLDOWN -> ChunkTranslator.translateSetCooldown757To759(packet.payload());
            case PLAY_ENTITY_EQUIPMENT -> ChunkTranslator.translateEntityEquipment757To759(packet.payload());
            case PLAY_TRADE_LIST -> ChunkTranslator.translateTradeList757To759(packet.payload());
            case PLAY_OPEN_WINDOW -> ChunkTranslator.translateOpenWindow757To759(packet.payload());
            case PLAY_BLOCK_ACTION -> ChunkTranslator.translateBlockAction757To759(packet.payload());
            case PLAY_SPAWN_ENTITY -> ChunkTranslator.translateSpawnEntity757To759(packet.payload());
            case PLAY_SOUND_EFFECT -> ChunkTranslator.translateSoundEffect757To759(packet.payload());
            case PLAY_ENTITY_SOUND_EFFECT -> ChunkTranslator.translateEntitySoundEffect757To759(packet.payload());
            case PLAY_NAMED_SOUND_EFFECT -> ChunkTranslator.translateNamedSoundEffect757To759(packet.payload());
            case PLAY_STOP_SOUND -> ChunkTranslator.translateStopSound757To759(packet.payload());
            case PLAY_WORLD_PARTICLES -> ChunkTranslator.translateWorldParticles757To759(packet.payload());
            case PLAY_ENTITY_EFFECT -> ChunkTranslator.translateEntityEffect757To759(packet.payload());
            case PLAY_REMOVE_ENTITY_EFFECT -> ChunkTranslator.translateRemoveEntityEffect757To759(packet.payload());
            case PLAY_ENTITY_UPDATE_ATTRIBUTES ->
                    // 同形式のため素通しする（minecraft-data 1.18／1.19でフィールド一致を確認。変換器は無い）。
                    packet.payload();
            case PLAY_CHUNK_DATA -> ChunkTranslator.translateChunkData757To759(packet.payload());
            case PLAY_BLOCK_CHANGE -> ChunkTranslator.translateBlockChange757To759(packet.payload());
            case PLAY_MULTI_BLOCK_CHANGE -> ChunkTranslator.translateMultiBlockChange757To759(packet.payload());
            case PLAY_BLOCK_ENTITY_DATA ->
                    // 同形式のため素通しする（minecraft-data 1.18／1.19でフィールド一致を確認。変換器は無い）。
                    packet.payload();
            case PLAY_EXPLOSION ->
                    // 同形式のため素通しする（minecraft-data 1.18／1.19でフィールド一致を確認。変換器は無い）。
                    packet.payload();
            case PLAY_ACKNOWLEDGE_PLAYER_DIGGING ->
                    // 757は location＋block＋status＋successful、759は sequenceId のみのため再構成できず落とす。
                    null;
            case PLAY_INITIALIZE_WORLD_BORDER -> ChunkTranslator.translateInitializeWorldBorder757To759(packet.payload());
            case PLAY_WORLD_BORDER_LERP_SIZE -> ChunkTranslator.translateWorldBorderLerpSize757To759(packet.payload());
            case PLAY_PLAYER_INFO_UPDATE -> PlayTranslator.translatePlayerInfo757To759(packet.payload());
            // 同形式のため素通しする（minecraft-data 1.18／1.19でフィールド一致を確認）。
            case PLAY_UPDATE_TIME, PLAY_HELD_ITEM_SLOT, PLAY_SYNCHRONIZE_PLAYER_POSITION,
                    PLAY_SPAWN_POSITION, PLAY_KEEP_ALIVE, PLAY_PING, PLAY_DISCONNECT ->
                    packet.payload();
            // 757の新規パケット：759に相当が無いため落とす。
            case PLAY_SCULK_VIBRATION_SIGNAL ->
                    // 759に相当が無いため落とす（sculk は1.19で別形式になった）。
                    null;
            default -> null;
        };
        if (translated == null) {
            logUntranslatedOnce(name);
            return null;
        }
        OptionalInt id759 = PacketTranslator.translateId(name,
                ProtocolVersion.V1_18, ProtocolVersion.V1_19);
        if (id759.isEmpty()) {
            logUntranslatedOnce(name);
            return null;
        }
        return new MinecraftPacket(id759.getAsInt(), translated);
    }

    /**
     * 内部774→クライアントのプレイ状態（サーバー→クライアント）。
     * Join Game／Respawn／Spawn Position／Keep Alive／Ping／Disconnect／
     * Start Configuration は773と同形式（ID も同じ）のため、773の処理を使い回す。
     * ただし773クライアントへの送出だけは774→773へ直すため、
     * Join Game／Respawn／Disconnect には773向けの分岐がある。
     * それ以外は774→773へ変換してから、773クライアントにはそのまま送り、
     * 767／766クライアントには既存の773→772／766の処理に通す。
     * 763／764／765クライアントは join レベルのみ（773と同じ）。
     */
    private Outcome handleServerPlayFrom774(MinecraftPacket packet) {
        // Start Configuration（774：0x74）。763には設定フェーズもこのパケットも無い。
        if (packet.id() == 0x74) {
            if (is763Like() || is757()) {
                serverState = ServerState.CONFIGURATION;
                reconfiguring = true;
                LOG.info(() -> "プレイ中の Start Configuration を受けました（" + playerName
                        + "）。サーバー側の設定フェーズを肩代わりします。");
                return Outcome.drop();
            }
            int outId = PacketTranslator.translateId(
                    PacketName.PLAY_START_CONFIGURATION, 774, clientProtocol)
                    .orElse(is764() ? 0x65 : 0x67);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        // Join Game（774：0x30）。
        if (packet.id() == 0x30) {
            return handleServerJoinGame774(packet);
        }
        // Spawn Position（774：0x5F）。
        if (packet.id() == 0x5F) {
            advanceFlowSafely(() -> joinFlow.spawned());
            int outId = PacketTranslator.translateId(
                    PacketName.PLAY_SPAWN_POSITION, 774, clientProtocolForServerPackets())
                    .orElse(is764() ? 0x52 : 0x54);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        // Keep Alive（774：0x2B）／Ping（774：0x3B）は接続維持のため中継する。
        if (packet.id() == 0x2B) {
            int outId = PacketTranslator.toClientId(PacketName.PLAY_KEEP_ALIVE,
                    serverProtocol, clientProtocolForServerPackets())
                    .orElse(is763Like() ? 0x23 : 0x24);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        if (packet.id() == 0x3B) {
            int outId = PacketTranslator.toClientId(PacketName.PLAY_PING,
                    serverProtocol, clientProtocolForServerPackets())
                    .orElse(is763Like() ? 0x32 : 0x33);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        // Disconnect（774：0x20、NBT）。
        if (packet.id() == 0x20) {
            closed = true;
            if (is763Like() || is764() || is757()) {
                byte[] payload = PlayTranslator.translateDisconnect765To763(packet.payload());
                int outId = (is763Like() || is757()) ? 0x1A : 0x1B;
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(outId, payload)), false, true);
            }
            if (is773() || is774() || is775()) {
                // 773／774／775クライアント：Disconnect は 0x20（NBT）のまま。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x20, packet.payload())), false, true);
            }
            if (is770() || is771() || is772()) {
                // 770／771／772クライアント：Disconnect は 0x1C（NBT）のまま。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x1C, packet.payload())), false, true);
            }
            if (is766() || is767() || is768() || is769()) {
                // 766／767／768／769クライアント：Disconnect は 0x1D（NBT）のまま。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x1D, packet.payload())), false, true);
            }
            return new Outcome(List.of(),
                    List.of(new MinecraftPacket(0x1B, packet.payload())), false, true);
        }
        // Respawn（774：0x50。773（0x50）と同形式のためそのまま送る）。
        if (packet.id() == 0x50) {
            if (is757()) {
                // 757クライアント：774の Respawn は dimensionType がキー形式で757と違うため落とす
                // （変換は PlayTranslator 担当。translateRespawn774To757 が要る）。
                logUntranslatedOnce(PacketName.PLAY_RESPAWN);
                return Outcome.drop();
            }
            if (is775()) {
                // 775クライアント：Respawn は 0x52（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x52, packet.payload()));
            }
            if (is773()) {
                // 773クライアント：Respawn は 0x50（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x50, packet.payload()));
            }
            if (is770() || is771() || is772()) {
                // 770／771／772クライアント：Respawn は 0x4B（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x4B, packet.payload()));
            }
            if (is768() || is769()) {
                // 768／769クライアント：Respawn は 0x4C（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x4C, packet.payload()));
            }
            byte[] payload767 = PlayTranslator.translateRespawn768To767(
                    packet.payload(), registries);
            if (is766() || is767()) {
                return Outcome.toClient(new MinecraftPacket(0x47, payload767));
            }
            byte[] payload;
            int outId;
            if (is763Like()) {
                payload = PlayTranslator.translateRespawn766To763(payload767, registries);
                outId = 0x41;
            } else if (is764()) {
                payload = PlayTranslator.translateRespawn766To764(payload767, registries);
                outId = 0x43;
            } else {
                payload = PlayTranslator.translateRespawn766To765(payload767, registries);
                outId = 0x45;
            }
            return Outcome.toClient(new MinecraftPacket(outId, payload));
        }
        // 775クライアント：774→775へ変換する。
        if (is775()) {
            return handleServerPlay774To775(packet);
        }
        // 773クライアント：774→773へ変換する。
        if (is773()) {
            return handleServerPlay774To773(packet);
        }
        // 772クライアント：774→773へ変換してから773→772へ。
        if (is772()) {
            MinecraftPacket as773 = to773ServerPacketFrom774(packet);
            if (as773 == null) {
                return Outcome.drop();
            }
            return handleServerPlay773To772(as773);
        }
        // 771クライアント：774→773→772へ変換してから772→771へ。
        if (is771()) {
            MinecraftPacket as773 = to773ServerPacketFrom774(packet);
            if (as773 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as772 = to772ServerPacketFrom773(as773);
            if (as772 == null) {
                return Outcome.drop();
            }
            return handleServerPlay772To771(as772);
        }
        // 770クライアント：774→773→772→771へ変換してから771→770へ。
        if (is770()) {
            MinecraftPacket as773 = to773ServerPacketFrom774(packet);
            if (as773 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as772 = to772ServerPacketFrom773(as773);
            if (as772 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as771 = to771ServerPacketFrom772(as772);
            if (as771 == null) {
                return Outcome.drop();
            }
            return handleServerPlay771To770(as771);
        }
        // 769クライアント：774→773→772→771へ変換してから771→769へ
        // （771→770→769は handleServerPlay771To769 の内側で変換）。
        if (is769()) {
            MinecraftPacket as773 = to773ServerPacketFrom774(packet);
            if (as773 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as772 = to772ServerPacketFrom773(as773);
            if (as772 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as771 = to771ServerPacketFrom772(as772);
            if (as771 == null) {
                return Outcome.drop();
            }
            return handleServerPlay771To769(as771);
        }
        // 768クライアント：774→773→772→771へ変換してから771→768へ
        // （771→770→769→768は handleServerPlay771To768 の内側で変換）。
        if (is768()) {
            MinecraftPacket as773 = to773ServerPacketFrom774(packet);
            if (as773 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as772 = to772ServerPacketFrom773(as773);
            if (as772 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as771 = to771ServerPacketFrom772(as772);
            if (as771 == null) {
                return Outcome.drop();
            }
            return handleServerPlay771To768(as771);
        }
        // 767クライアント：774→773→772→771→770→769→768へ変換してから769→768へ。
        if (is767()) {
            MinecraftPacket as773 = to773ServerPacketFrom774(packet);
            if (as773 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as772 = to772ServerPacketFrom773(as773);
            if (as772 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as771 = to771ServerPacketFrom772(as772);
            if (as771 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as770 = to770ServerPacketFrom771(as771);
            if (as770 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as769 = to769ServerPacketFrom770(as770);
            if (as769 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as768 = to768ServerPacket(as769);
            if (as768 == null) {
                return Outcome.drop();
            }
            return handleServerPlay768To767(as768);
        }
        // 766クライアント：774→773→772→771→770→769→768へ変換してから769→767へ。
        if (is766()) {
            MinecraftPacket as773 = to773ServerPacketFrom774(packet);
            if (as773 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as772 = to772ServerPacketFrom773(as773);
            if (as772 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as771 = to771ServerPacketFrom772(as772);
            if (as771 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as770 = to770ServerPacketFrom771(as771);
            if (as770 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as769 = to769ServerPacketFrom770(as770);
            if (as769 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as768 = to768ServerPacket(as769);
            if (as768 == null) {
                return Outcome.drop();
            }
            return handleServerPlay768To766(as768);
        }
        // それ以外は落とす（763／764／765クライアントは join レベルのみ）。
        PacketName name = PacketIds.nameFor(packet.id(), State.PLAY,
                Direction.CLIENTBOUND, 774).orElse(null);
        if (name == null) {
            logUntranslatedOnce("PLAY_UNKNOWN_0x" + Integer.toHexString(packet.id()));
        } else {
            logUntranslatedOnce(name);
        }
        return Outcome.drop();
    }

    /**
     * Join Game（内部774：0x30）のクライアント向け変換。
     * 773と同形式のため、773クライアントにはそのまま送る。
     * それ以外は {@link #handleServerJoinGame773} と同じ方針で各クライアントへ送る。
     */
    private Outcome handleServerJoinGame774(MinecraftPacket packet) {
        if (is757()) {
            // 757クライアント：774の Join Game は dimensionType がキー形式で757と違うため落とす
            // （変換は PlayTranslator 担当。translateJoinGame774To757 が要る）。
            logUntranslatedOnce(PacketName.PLAY_JOIN_GAME);
            return Outcome.drop();
        }
        if (is775()) {
            advanceFlowSafely(() -> joinFlow.joinGameReceived());
            List<MinecraftPacket> toClient = new ArrayList<>();
            toClient.add(new MinecraftPacket(0x31, packet.payload()));
            while (!pendingPacks.isEmpty()) {
                PendingPack pack = pendingPacks.removeFirst();
                lastSentPack = pack;
                toClient.add(new MinecraftPacket(0x51,
                        PlayTranslator.translateConfigAddResourcePack764To765(
                                pack, packOverrideForClient())));
            }
            return new Outcome(List.of(), toClient, false, false);
        }
        if (is773()) {
            advanceFlowSafely(() -> joinFlow.joinGameReceived());
            List<MinecraftPacket> toClient = new ArrayList<>();
            toClient.add(new MinecraftPacket(0x30, packet.payload()));
            while (!pendingPacks.isEmpty()) {
                PendingPack pack = pendingPacks.removeFirst();
                lastSentPack = pack;
                toClient.add(new MinecraftPacket(0x4F,
                        PlayTranslator.translateConfigAddResourcePack764To765(
                                pack, packOverrideForClient())));
            }
            return new Outcome(List.of(), toClient, false, false);
        }
        return handleServerJoinGame773(packet);
    }

    /**
     * 774サーバーのプレイ状態パケットを773形式にする。773に相当が無い／
     * 変換できないものは null を返す（ログ済み）。
     * 773クライアントへの送出と、767／766クライアントへの二段変換の
     * 第一段で共用する。
     */
    private MinecraftPacket to773ServerPacketFrom774(MinecraftPacket packet) {
        PacketName name = PacketIds.nameFor(packet.id(), State.PLAY,
                Direction.CLIENTBOUND, ProtocolVersion.V1_21_11).orElse(null);
        // experience_orb：771・772・773・774とも通常の Spawn Entity
        // （type experience_orb）のため、専用の分岐は要らない
        // （下の PLAY_SPAWN_ENTITY 経路で通す）。
        if (name == null) {
            logUntranslatedOnce("PLAY_UNKNOWN_0x" + Integer.toHexString(packet.id()));
            return null;
        }
        byte[] translated = switch (name) {
            case PLAY_ENTITY_METADATA ->
                    ChunkTranslator.translateEntityMetadata774To773(packet.payload());
            case PLAY_SET_SLOT ->
                    ChunkTranslator.translateSetSlot774To773(packet.payload());
            case PLAY_SET_CURSOR_ITEM ->
                    ChunkTranslator.translateSetCursorItem774To773(packet.payload());
            case PLAY_SET_PLAYER_INVENTORY ->
                    ChunkTranslator.translateSetPlayerInventory774To773(packet.payload());
            case PLAY_WINDOW_ITEMS ->
                    ChunkTranslator.translateWindowItems774To773(packet.payload());
            case PLAY_SET_COOLDOWN ->
                    ChunkTranslator.translateSetCooldown774To773(packet.payload());
            case PLAY_ENTITY_EQUIPMENT ->
                    ChunkTranslator.translateEntityEquipment774To773(packet.payload());
            case PLAY_TRADE_LIST ->
                    ChunkTranslator.translateTradeList774To773(packet.payload());
            case PLAY_OPEN_WINDOW ->
                    ChunkTranslator.translateOpenWindow774To773(packet.payload());
            case PLAY_BLOCK_ACTION ->
                    ChunkTranslator.translateBlockAction774To773(packet.payload());
            case PLAY_SPAWN_ENTITY ->
                    ChunkTranslator.translateSpawnEntity774To773(packet.payload());
            case PLAY_SOUND_EFFECT ->
                    ChunkTranslator.translateSoundEffect774To773(packet.payload());
            case PLAY_ENTITY_SOUND_EFFECT ->
                    ChunkTranslator.translateEntitySoundEffect774To773(packet.payload());
            case PLAY_STOP_SOUND ->
                    ChunkTranslator.translateStopSound774To773(packet.payload());
            case PLAY_WORLD_PARTICLES ->
                    ChunkTranslator.translateWorldParticles774To773(packet.payload());
            case PLAY_ENTITY_EFFECT ->
                    ChunkTranslator.translateEntityEffect774To773(packet.payload());
            case PLAY_REMOVE_ENTITY_EFFECT ->
                    ChunkTranslator.translateRemoveEntityEffect774To773(packet.payload());
            case PLAY_DAMAGE_EVENT ->
                    ChunkTranslator.translateDamageEvent774To773(packet.payload());
            case PLAY_ENTITY_UPDATE_ATTRIBUTES ->
                    ChunkTranslator.translateUpdateAttributes774To773(packet.payload());
            case PLAY_CHUNK_DATA ->
                    ChunkTranslator.translateChunkData774To773(packet.payload());
            case PLAY_BLOCK_CHANGE ->
                    ChunkTranslator.translateBlockChange774To773(packet.payload());
            case PLAY_MULTI_BLOCK_CHANGE ->
                    ChunkTranslator.translateMultiBlockChange774To773(packet.payload());
            case PLAY_BLOCK_ENTITY_DATA ->
                    ChunkTranslator.translateBlockEntityData774To773(packet.payload());
            case PLAY_PLAYER_INFO_UPDATE ->
                    PlayTranslator.translatePlayerInfo774To773(packet.payload());
            case PLAY_PLAYER_CHAT ->
                    PlayTranslator.translatePlayerChat774To773(packet.payload());
            case PLAY_SYSTEM_CHAT, PLAY_PROFILELESS_CHAT ->
                    packet.payload(); // 同形式
            case PLAY_SYNCHRONIZE_PLAYER_POSITION, PLAY_UPDATE_TIME, PLAY_SET_SLOT_STATE ->
                    packet.payload(); // 同形式
            case PLAY_HELD_ITEM_SLOT ->
                    PlayTranslator.translateSetHeldItem774To773(packet.payload());
            case PLAY_EXPLOSION ->
                    ChunkTranslator.translateExplosion774To773(packet.payload());
            // ロケーターバー／ダイアログは773にもあるためそのまま通す（同形式）。
            case PLAY_TRACKED_WAYPOINT, PLAY_SHOW_DIALOG, PLAY_CLEAR_DIALOG ->
                    packet.payload();
            default -> null;
        };
        if (translated == null) {
            logUntranslatedOnce(name);
            return null;
        }
        OptionalInt id773 = PacketTranslator.translateId(name,
                ProtocolVersion.V1_21_11, ProtocolVersion.V1_21_9);
        if (id773.isEmpty()) {
            logUntranslatedOnce(name);
            return null;
        }
        return new MinecraftPacket(id773.getAsInt(), translated);
    }

    /**
     * 内部774→773クライアントのプレイ状態（サーバー→クライアント）。
     * 774→773へ変換してそのまま送る。
     */
    private Outcome handleServerPlay774To773(MinecraftPacket packet) {
        MinecraftPacket as773 = to773ServerPacketFrom774(packet);
        if (as773 == null) {
            return Outcome.drop();
        }
        return Outcome.toClient(as773);
    }

    /**
     * 内部773→クライアントのプレイ状態（サーバー→クライアント）。
     * Join Game／Respawn／Spawn Position／Keep Alive／Ping／Disconnect／
     * Start Configuration は772と同形式だが ID が変わる（Join Game 0x2B→0x30、
     * Respawn 0x4B→0x50、Spawn Position 0x5A→0x5F、Keep Alive 0x26→0x2B、
     * Ping 0x36→0x3B、Disconnect 0x1C→0x20、Start Configuration 0x6F→0x74）
     * ため、773の番号で振り分ける。
     * ただし772クライアントへの送出だけは773→772へ直すため、
     * Join Game／Respawn／Disconnect には772向けの分岐がある。
     * それ以外は773→772へ変換してから、772クライアントにはそのまま送り、
     * 767／766クライアントには既存の772→771／766の処理に通す。
     * 763／764／765クライアントは join レベルのみ（772と同じ）。
     */
    private Outcome handleServerPlayFrom773(MinecraftPacket packet) {
        // Start Configuration（773：0x74）。763には設定フェーズもこのパケットも無い。
        if (packet.id() == 0x74) {
            if (is763Like() || is757()) {
                serverState = ServerState.CONFIGURATION;
                reconfiguring = true;
                LOG.info(() -> "プレイ中の Start Configuration を受けました（" + playerName
                        + "）。サーバー側の設定フェーズを肩代わりします。");
                return Outcome.drop();
            }
            int outId = PacketTranslator.translateId(
                    PacketName.PLAY_START_CONFIGURATION, 773, clientProtocol)
                    .orElse(is764() ? 0x65 : 0x67);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        // Join Game（773：0x30）。
        if (packet.id() == 0x30) {
            return handleServerJoinGame773(packet);
        }
        // Spawn Position（773：0x5F）。
        if (packet.id() == 0x5F) {
            advanceFlowSafely(() -> joinFlow.spawned());
            int outId = PacketTranslator.translateId(
                    PacketName.PLAY_SPAWN_POSITION, 773, clientProtocolForServerPackets())
                    .orElse(is764() ? 0x52 : 0x54);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        // Keep Alive（773：0x2B）／Ping（773：0x3B）は接続維持のため中継する。
        if (packet.id() == 0x2B) {
            int outId = PacketTranslator.toClientId(PacketName.PLAY_KEEP_ALIVE,
                    serverProtocol, clientProtocolForServerPackets())
                    .orElse(is763Like() ? 0x23 : 0x24);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        if (packet.id() == 0x3B) {
            int outId = PacketTranslator.toClientId(PacketName.PLAY_PING,
                    serverProtocol, clientProtocolForServerPackets())
                    .orElse(is763Like() ? 0x32 : 0x33);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        // Disconnect（773：0x20、NBT）。
        if (packet.id() == 0x20) {
            closed = true;
            if (is763Like() || is764() || is757()) {
                byte[] payload = PlayTranslator.translateDisconnect765To763(packet.payload());
                int outId = (is763Like() || is757()) ? 0x1A : 0x1B;
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(outId, payload)), false, true);
            }
            if (is773() || is774() || is775()) {
                // 773／774／775クライアント：Disconnect は 0x20（NBT）。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x20, packet.payload())), false, true);
            }
            if (is771() || is772()) {
                // 771／772クライアント：Disconnect は 0x1C（NBT）のまま。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x1C, packet.payload())), false, true);
            }
            if (is766() || is767() || is768() || is769()) {
                // 766／767／768／769クライアント：Disconnect は 0x1D（NBT）のまま。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x1D, packet.payload())), false, true);
            }
            if (is770()) {
                // 770クライアント：Disconnect は 0x1C（NBT）のまま。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x1C, packet.payload())), false, true);
            }
            return new Outcome(List.of(),
                    List.of(new MinecraftPacket(0x1B, packet.payload())), false, true);
        }
        // Respawn（774：0x50。772（0x4B）と同形式のためそのまま送る）。
        if (packet.id() == 0x50) {
            if (is757()) {
                // 757クライアント：773の Respawn は dimensionType がキー形式で757と違うため落とす
                // （変換は PlayTranslator 担当。translateRespawn773To757 が要る）。
                logUntranslatedOnce(PacketName.PLAY_RESPAWN);
                return Outcome.drop();
            }
            if (is775()) {
                // 775クライアント：Respawn は 0x52（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x52, packet.payload()));
            }
            if (is774()) {
                // 774クライアント：Respawn は 0x50（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x50, packet.payload()));
            }
            if (is773()) {
                // 773クライアント：Respawn は 0x50（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x50, packet.payload()));
            }
            if (is772()) {
                // 772クライアント：Respawn は 0x4B（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x4B, packet.payload()));
            }
            if (is770()) {
                // 770クライアント：Respawn は 0x4B（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x4B, packet.payload()));
            }
            if (is768() || is769()) {
                // 768／769クライアント：Respawn は 0x4C（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x4C, packet.payload()));
            }
            byte[] payload767 = PlayTranslator.translateRespawn768To767(
                    packet.payload(), registries);
            if (is766() || is767()) {
                return Outcome.toClient(new MinecraftPacket(0x47, payload767));
            }
            byte[] payload;
            int outId;
            if (is763Like()) {
                payload = PlayTranslator.translateRespawn766To763(payload767, registries);
                outId = 0x41;
            } else if (is764()) {
                payload = PlayTranslator.translateRespawn766To764(payload767, registries);
                outId = 0x43;
            } else {
                payload = PlayTranslator.translateRespawn766To765(payload767, registries);
                outId = 0x45;
            }
            return Outcome.toClient(new MinecraftPacket(outId, payload));
        }
        // 775クライアント：773→774→775へ二段で変換する。
        if (is775()) {
            return handleServerPlay773To775(packet);
        }
        // 774クライアント：773→774へ変換する。
        if (is774()) {
            return handleServerPlay773To774(packet);
        }
        // 772クライアント：773→772へ変換する。
        if (is772()) {
            return handleServerPlay773To772(packet);
        }
        // 771クライアント：773→772へ変換してから772→771へ。
        if (is771()) {
            MinecraftPacket as772 = to772ServerPacketFrom773(packet);
            if (as772 == null) {
                return Outcome.drop();
            }
            return handleServerPlay772To771(as772);
        }
        // 770クライアント：773→772→771へ変換してから771→770へ。
        if (is770()) {
            MinecraftPacket as772 = to772ServerPacketFrom773(packet);
            if (as772 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as771 = to771ServerPacketFrom772(as772);
            if (as771 == null) {
                return Outcome.drop();
            }
            return handleServerPlay771To770(as771);
        }
        // 769クライアント：773→772→771へ変換してから771→769へ
        // （771→770→769は handleServerPlay771To769 の内側で変換）。
        if (is769()) {
            MinecraftPacket as772 = to772ServerPacketFrom773(packet);
            if (as772 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as771 = to771ServerPacketFrom772(as772);
            if (as771 == null) {
                return Outcome.drop();
            }
            return handleServerPlay771To769(as771);
        }
        // 768クライアント：773→772→771へ変換してから771→768へ
        // （771→770→769→768は handleServerPlay771To768 の内側で変換）。
        if (is768()) {
            MinecraftPacket as772 = to772ServerPacketFrom773(packet);
            if (as772 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as771 = to771ServerPacketFrom772(as772);
            if (as771 == null) {
                return Outcome.drop();
            }
            return handleServerPlay771To768(as771);
        }
        // 767クライアント：773→772→771→770→769→768へ変換してから769→768へ。
        if (is767()) {
            MinecraftPacket as772 = to772ServerPacketFrom773(packet);
            if (as772 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as771 = to771ServerPacketFrom772(as772);
            if (as771 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as770 = to770ServerPacketFrom771(as771);
            if (as770 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as769 = to769ServerPacketFrom770(as770);
            if (as769 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as768 = to768ServerPacket(as769);
            if (as768 == null) {
                return Outcome.drop();
            }
            return handleServerPlay768To767(as768);
        }
        // 766クライアント：773→772→771→770→769→768へ変換してから769→767へ。
        if (is766()) {
            MinecraftPacket as772 = to772ServerPacketFrom773(packet);
            if (as772 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as771 = to771ServerPacketFrom772(as772);
            if (as771 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as770 = to770ServerPacketFrom771(as771);
            if (as770 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as769 = to769ServerPacketFrom770(as770);
            if (as769 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as768 = to768ServerPacket(as769);
            if (as768 == null) {
                return Outcome.drop();
            }
            return handleServerPlay768To766(as768);
        }
        // それ以外は落とす（763／764／765クライアントは join レベルのみ）。
        PacketName name = PacketIds.nameFor(packet.id(), State.PLAY,
                Direction.CLIENTBOUND, 773).orElse(null);
        if (name == null) {
            logUntranslatedOnce("PLAY_UNKNOWN_0x" + Integer.toHexString(packet.id()));
        } else {
            logUntranslatedOnce(name);
        }
        return Outcome.drop();
    }

    /**
     * Join Game（内部773：0x30）のクライアント向け変換。
     * 772と同形式のため、772クライアントにはそのまま送る。
     * それ以外は {@link #handleServerJoinGame772} と同じ方針で各クライアントへ送る。
     */
    private Outcome handleServerJoinGame773(MinecraftPacket packet) {
        if (is757()) {
            // 757クライアント：773の Join Game は dimensionType がキー形式で757と違うため落とす
            // （変換は PlayTranslator 担当。translateJoinGame773To757 が要る）。
            logUntranslatedOnce(PacketName.PLAY_JOIN_GAME);
            return Outcome.drop();
        }
        if (is772()) {
            advanceFlowSafely(() -> joinFlow.joinGameReceived());
            List<MinecraftPacket> toClient = new ArrayList<>();
            toClient.add(new MinecraftPacket(0x2B, packet.payload()));
            while (!pendingPacks.isEmpty()) {
                PendingPack pack = pendingPacks.removeFirst();
                lastSentPack = pack;
                toClient.add(new MinecraftPacket(0x4A,
                        PlayTranslator.translateConfigAddResourcePack764To765(
                                pack, packOverrideForClient())));
            }
            return new Outcome(List.of(), toClient, false, false);
        }
        return handleServerJoinGame772(packet);
    }

    /**
     * 773サーバーのプレイ状態パケットを772形式にする。772に相当が無い／
     * 変換できないものは null を返す（ログ済み）。
     * 772クライアントへの送出と、767／766クライアントへの二段変換の
     * 第一段で共用する。
     */
    private MinecraftPacket to772ServerPacketFrom773(MinecraftPacket packet) {
        PacketName name = PacketIds.nameFor(packet.id(), State.PLAY,
                Direction.CLIENTBOUND, ProtocolVersion.V1_21_9).orElse(null);
        // experience_orb：771・772・773とも通常の Spawn Entity
        // （type experience_orb）のため、専用の分岐は要らない
        // （下の PLAY_SPAWN_ENTITY 経路で通す）。
        if (name == null) {
            logUntranslatedOnce("PLAY_UNKNOWN_0x" + Integer.toHexString(packet.id()));
            return null;
        }
        byte[] translated = switch (name) {
            case PLAY_ENTITY_METADATA ->
                    ChunkTranslator.translateEntityMetadata773To772(packet.payload());
            case PLAY_SET_SLOT ->
                    ChunkTranslator.translateSetSlot773To772(packet.payload());
            case PLAY_SET_CURSOR_ITEM ->
                    ChunkTranslator.translateSetCursorItem773To772(packet.payload());
            case PLAY_SET_PLAYER_INVENTORY ->
                    ChunkTranslator.translateSetPlayerInventory773To772(packet.payload());
            case PLAY_WINDOW_ITEMS ->
                    ChunkTranslator.translateWindowItems773To772(packet.payload());
            case PLAY_SET_COOLDOWN ->
                    ChunkTranslator.translateSetCooldown773To772(packet.payload());
            case PLAY_ENTITY_EQUIPMENT ->
                    ChunkTranslator.translateEntityEquipment773To772(packet.payload());
            case PLAY_TRADE_LIST ->
                    ChunkTranslator.translateTradeList773To772(packet.payload());
            case PLAY_OPEN_WINDOW ->
                    ChunkTranslator.translateOpenWindow773To772(packet.payload());
            case PLAY_BLOCK_ACTION ->
                    ChunkTranslator.translateBlockAction773To772(packet.payload());
            case PLAY_SPAWN_ENTITY ->
                    ChunkTranslator.translateSpawnEntity773To772(packet.payload());
            case PLAY_SOUND_EFFECT ->
                    ChunkTranslator.translateSoundEffect773To772(packet.payload());
            case PLAY_ENTITY_SOUND_EFFECT ->
                    ChunkTranslator.translateEntitySoundEffect773To772(packet.payload());
            case PLAY_STOP_SOUND ->
                    ChunkTranslator.translateStopSound773To772(packet.payload());
            case PLAY_WORLD_PARTICLES ->
                    ChunkTranslator.translateWorldParticles773To772(packet.payload());
            case PLAY_ENTITY_EFFECT ->
                    ChunkTranslator.translateEntityEffect773To772(packet.payload());
            case PLAY_REMOVE_ENTITY_EFFECT ->
                    ChunkTranslator.translateRemoveEntityEffect773To772(packet.payload());
            case PLAY_DAMAGE_EVENT ->
                    ChunkTranslator.translateDamageEvent773To772(packet.payload());
            case PLAY_ENTITY_UPDATE_ATTRIBUTES ->
                    ChunkTranslator.translateUpdateAttributes773To772(packet.payload());
            case PLAY_CHUNK_DATA ->
                    ChunkTranslator.translateChunkData773To772(packet.payload());
            case PLAY_BLOCK_CHANGE ->
                    ChunkTranslator.translateBlockChange773To772(packet.payload());
            case PLAY_MULTI_BLOCK_CHANGE ->
                    ChunkTranslator.translateMultiBlockChange773To772(packet.payload());
            case PLAY_BLOCK_ENTITY_DATA ->
                    ChunkTranslator.translateBlockEntityData773To772(packet.payload());
            case PLAY_PLAYER_INFO_UPDATE ->
                    PlayTranslator.translatePlayerInfo773To772(packet.payload());
            case PLAY_PLAYER_CHAT ->
                    PlayTranslator.translatePlayerChat773To772(packet.payload());
            case PLAY_SYSTEM_CHAT, PLAY_PROFILELESS_CHAT ->
                    packet.payload(); // 同形式
            case PLAY_SYNCHRONIZE_PLAYER_POSITION, PLAY_UPDATE_TIME, PLAY_SET_SLOT_STATE ->
                    packet.payload(); // 同形式
            case PLAY_HELD_ITEM_SLOT ->
                    PlayTranslator.translateSetHeldItem773To772(packet.payload());
            case PLAY_EXPLOSION ->
                    ChunkTranslator.translateExplosion773To772(packet.payload());
            // ロケーターバー／ダイアログは772にもあるためそのまま通す（同形式）。
            case PLAY_TRACKED_WAYPOINT, PLAY_SHOW_DIALOG, PLAY_CLEAR_DIALOG ->
                    packet.payload();
            default -> null;
        };
        if (translated == null) {
            logUntranslatedOnce(name);
            return null;
        }
        OptionalInt id772 = PacketTranslator.translateId(name,
                ProtocolVersion.V1_21_9, ProtocolVersion.V1_21_7);
        if (id772.isEmpty()) {
            logUntranslatedOnce(name);
            return null;
        }
        return new MinecraftPacket(id772.getAsInt(), translated);
    }

    /**
     * 内部773→772クライアントのプレイ状態（サーバー→クライアント）。
     * 773→772へ変換してそのまま送る。
     */
    private Outcome handleServerPlay773To772(MinecraftPacket packet) {
        MinecraftPacket as772 = to772ServerPacketFrom773(packet);
        if (as772 == null) {
            return Outcome.drop();
        }
        return Outcome.toClient(as772);
    }

    /**
     * 内部772→クライアントのプレイ状態（サーバー→クライアント）。
     * Join Game／Respawn／Spawn Position／Keep Alive／Ping／Disconnect／
     * Start Configuration は771と同形式（ID も同じ）のため、771の処理を使い回す。
     * ただし771クライアントへの送出だけは772→771へ直すため、
     * Join Game／Respawn／Disconnect には771向けの分岐がある。
     * それ以外は772→771へ変換してから、771クライアントにはそのまま送り、
     * 767／766クライアントには既存の771→770／766の処理に通す。
     * 763／764／765クライアントは join レベルのみ（771と同じ）。
     */
    private Outcome handleServerPlayFrom772(MinecraftPacket packet) {
        // Start Configuration（772：0x6F）。763には設定フェーズもこのパケットも無い。
        if (packet.id() == 0x6F) {
            if (is763Like() || is757()) {
                serverState = ServerState.CONFIGURATION;
                reconfiguring = true;
                LOG.info(() -> "プレイ中の Start Configuration を受けました（" + playerName
                        + "）。サーバー側の設定フェーズを肩代わりします。");
                return Outcome.drop();
            }
            int outId = PacketTranslator.translateId(
                    PacketName.PLAY_START_CONFIGURATION, 772, clientProtocol)
                    .orElse(is764() ? 0x65 : 0x67);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        // Join Game（772：0x2B）。
        if (packet.id() == 0x2B) {
            return handleServerJoinGame772(packet);
        }
        // Spawn Position（772：0x5A）。
        if (packet.id() == 0x5A) {
            advanceFlowSafely(() -> joinFlow.spawned());
            int outId = PacketTranslator.translateId(
                    PacketName.PLAY_SPAWN_POSITION, 772, clientProtocolForServerPackets())
                    .orElse(is764() ? 0x52 : 0x54);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        // Keep Alive（772：0x26）／Ping（772：0x36）は接続維持のため中継する。
        if (packet.id() == 0x26) {
            int outId = PacketTranslator.toClientId(PacketName.PLAY_KEEP_ALIVE,
                    serverProtocol, clientProtocolForServerPackets())
                    .orElse(is763Like() ? 0x23 : 0x24);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        if (packet.id() == 0x36) {
            int outId = PacketTranslator.toClientId(PacketName.PLAY_PING,
                    serverProtocol, clientProtocolForServerPackets())
                    .orElse(is763Like() ? 0x32 : 0x33);
            return Outcome.toClient(new MinecraftPacket(outId, packet.payload()));
        }
        // Disconnect（772：0x1C、NBT）。
        if (packet.id() == 0x1C) {
            closed = true;
            if (is763Like() || is764() || is757()) {
                byte[] payload = PlayTranslator.translateDisconnect765To763(packet.payload());
                int outId = (is763Like() || is757()) ? 0x1A : 0x1B;
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(outId, payload)), false, true);
            }
            if (is773() || is774() || is775()) {
                // 773／774／775クライアント：Disconnect は 0x20（NBT）。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x20, packet.payload())), false, true);
            }
            if (is771() || is772()) {
                // 771／772クライアント：Disconnect は 0x1C（NBT）のまま。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x1C, packet.payload())), false, true);
            }
            if (is766() || is767() || is768() || is769()) {
                // 766／767／768／769クライアント：Disconnect は 0x1D（NBT）のまま。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x1D, packet.payload())), false, true);
            }
            if (is770()) {
                // 770クライアント：Disconnect は 0x1C（NBT）のまま。
                return new Outcome(List.of(),
                        List.of(new MinecraftPacket(0x1C, packet.payload())), false, true);
            }
            return new Outcome(List.of(),
                    List.of(new MinecraftPacket(0x1B, packet.payload())), false, true);
        }
        // Respawn（772：0x4B。771（0x4B）と同形式のためそのまま送る）。
        if (packet.id() == 0x4B) {
            if (is757()) {
                // 757クライアント：772の Respawn は dimensionType がキー形式で757と違うため落とす
                // （変換は PlayTranslator 担当。translateRespawn772To757 が要る）。
                logUntranslatedOnce(PacketName.PLAY_RESPAWN);
                return Outcome.drop();
            }
            if (is771()) {
                // 771クライアント：Respawn は 0x4B（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x4B, packet.payload()));
            }
            if (is775()) {
                // 775クライアント：Respawn は 0x52（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x52, packet.payload()));
            }
            if (is774()) {
                // 774クライアント：Respawn は 0x50（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x50, packet.payload()));
            }
            if (is773()) {
                // 773クライアント：Respawn は 0x50（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x50, packet.payload()));
            }
            if (is770()) {
                // 770クライアント：Respawn は 0x4B（同形式）のまま。
                return Outcome.toClient(new MinecraftPacket(0x4B, packet.payload()));
            }
            if (is768() || is769()) {
                // 768／769クライアント：Respawn は 0x4C（同形式）のまま。
                // 771段階で追加された分岐の772版。無いと 765形式の 0x45 に落ちる。
                return Outcome.toClient(new MinecraftPacket(0x4C, packet.payload()));
            }
            byte[] payload767 = PlayTranslator.translateRespawn768To767(
                    packet.payload(), registries);
            if (is766() || is767()) {
                return Outcome.toClient(new MinecraftPacket(0x47, payload767));
            }
            byte[] payload;
            int outId;
            if (is763Like()) {
                payload = PlayTranslator.translateRespawn766To763(payload767, registries);
                outId = 0x41;
            } else if (is764()) {
                payload = PlayTranslator.translateRespawn766To764(payload767, registries);
                outId = 0x43;
            } else {
                payload = PlayTranslator.translateRespawn766To765(payload767, registries);
                outId = 0x45;
            }
            return Outcome.toClient(new MinecraftPacket(outId, payload));
        }
        // 771クライアント：772→771へ変換する。
        if (is771()) {
            return handleServerPlay772To771(packet);
        }
        // 775クライアント：772→775へ変換する。
        if (is775()) {
            return handleServerPlay772To775(packet);
        }
        // 774クライアント：772→774へ変換する。
        if (is774()) {
            return handleServerPlay772To774(packet);
        }
        // 773クライアント：772→773へ変換する。
        if (is773()) {
            return handleServerPlay772To773(packet);
        }
        // 770クライアント：772→771へ変換してから771→770へ。
        if (is770()) {
            MinecraftPacket as771 = to771ServerPacketFrom772(packet);
            if (as771 == null) {
                return Outcome.drop();
            }
            return handleServerPlay771To770(as771);
        }
        // 769クライアント：772→771へ変換してから771→769へ
        // （771→770→769は handleServerPlay771To769 の内側で変換）。
        if (is769()) {
            MinecraftPacket as771 = to771ServerPacketFrom772(packet);
            if (as771 == null) {
                return Outcome.drop();
            }
            return handleServerPlay771To769(as771);
        }
        // 768クライアント：772→771へ変換してから771→768へ
        // （771→770→769→768は handleServerPlay771To768 の内側で変換）。
        if (is768()) {
            MinecraftPacket as771 = to771ServerPacketFrom772(packet);
            if (as771 == null) {
                return Outcome.drop();
            }
            return handleServerPlay771To768(as771);
        }
        // 767クライアント：772→771→770→769→768へ変換してから768→767へ。
        if (is767()) {
            MinecraftPacket as771 = to771ServerPacketFrom772(packet);
            if (as771 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as770 = to770ServerPacketFrom771(as771);
            if (as770 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as769 = to769ServerPacketFrom770(as770);
            if (as769 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as768 = to768ServerPacket(as769);
            if (as768 == null) {
                return Outcome.drop();
            }
            return handleServerPlay768To767(as768);
        }
        // 766クライアント：772→771→770→769→768へ変換してから768→766へ。
        if (is766()) {
            MinecraftPacket as771 = to771ServerPacketFrom772(packet);
            if (as771 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as770 = to770ServerPacketFrom771(as771);
            if (as770 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as769 = to769ServerPacketFrom770(as770);
            if (as769 == null) {
                return Outcome.drop();
            }
            MinecraftPacket as768 = to768ServerPacket(as769);
            if (as768 == null) {
                return Outcome.drop();
            }
            return handleServerPlay768To766(as768);
        }
        // それ以外は落とす（763／764／765クライアントは join レベルのみ）。
        PacketName name = PacketIds.nameFor(packet.id(), State.PLAY,
                Direction.CLIENTBOUND, 772).orElse(null);
        if (name == null) {
            logUntranslatedOnce("PLAY_UNKNOWN_0x" + Integer.toHexString(packet.id()));
        } else {
            logUntranslatedOnce(name);
        }
        return Outcome.drop();
    }

    /**
     * Join Game（内部772：0x2B）のクライアント向け変換。
     * 771と同形式のため、771クライアントにはそのまま送る。
     * それ以外は {@link #handleServerJoinGame771} と同じ方針で各クライアントへ送る。
     */
    private Outcome handleServerJoinGame772(MinecraftPacket packet) {
        if (is757()) {
            // 757クライアント：772の Join Game は dimensionType がキー形式で757と違うため落とす
            // （変換は PlayTranslator 担当。translateJoinGame772To757 が要る）。
            logUntranslatedOnce(PacketName.PLAY_JOIN_GAME);
            return Outcome.drop();
        }
        if (is775()) {
            advanceFlowSafely(() -> joinFlow.joinGameReceived());
            List<MinecraftPacket> toClient = new ArrayList<>();
            toClient.add(new MinecraftPacket(0x31, packet.payload()));
            while (!pendingPacks.isEmpty()) {
                PendingPack pack = pendingPacks.removeFirst();
                lastSentPack = pack;
                toClient.add(new MinecraftPacket(0x51,
                        PlayTranslator.translateConfigAddResourcePack764To765(
                                pack, packOverrideForClient())));
            }
            return new Outcome(List.of(), toClient, false, false);
        }
        if (is774()) {
            advanceFlowSafely(() -> joinFlow.joinGameReceived());
            List<MinecraftPacket> toClient = new ArrayList<>();
            toClient.add(new MinecraftPacket(0x30, packet.payload()));
            while (!pendingPacks.isEmpty()) {
                PendingPack pack = pendingPacks.removeFirst();
                lastSentPack = pack;
                toClient.add(new MinecraftPacket(0x4F,
                        PlayTranslator.translateConfigAddResourcePack764To765(
                                pack, packOverrideForClient())));
            }
            return new Outcome(List.of(), toClient, false, false);
        }
        if (is773()) {
            advanceFlowSafely(() -> joinFlow.joinGameReceived());
            List<MinecraftPacket> toClient = new ArrayList<>();
            toClient.add(new MinecraftPacket(0x30, packet.payload()));
            while (!pendingPacks.isEmpty()) {
                PendingPack pack = pendingPacks.removeFirst();
                lastSentPack = pack;
                toClient.add(new MinecraftPacket(0x4F,
                        PlayTranslator.translateConfigAddResourcePack764To765(
                                pack, packOverrideForClient())));
            }
            return new Outcome(List.of(), toClient, false, false);
        }
        if (is771()) {
            advanceFlowSafely(() -> joinFlow.joinGameReceived());
            List<MinecraftPacket> toClient = new ArrayList<>();
            toClient.add(new MinecraftPacket(0x2B, packet.payload()));
            while (!pendingPacks.isEmpty()) {
                PendingPack pack = pendingPacks.removeFirst();
                lastSentPack = pack;
                toClient.add(new MinecraftPacket(0x4A,
                        PlayTranslator.translateConfigAddResourcePack764To765(
                                pack, packOverrideForClient())));
            }
            return new Outcome(List.of(), toClient, false, false);
        }
        return handleServerJoinGame771(packet);
    }

